#!/usr/bin/env python3
"""Preserve historical compact-header checks and strengthen actual centerline geometry."""
import hashlib,json
from pathlib import Path
original=Path(__file__).with_name("2026-11-16-compact-player-header-regression.py")
raw=original.read_bytes()
assert hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()=="2d310ab51e8182ebc2e2f90f523bb7c6dad5f8a7",original
source=raw.decode("utf-8")
for old,replacement,count in json.loads("[[\"return {bar:rect(bar),title:rect(title),back:rect(back),frame:rect(frame),nav:rect(nav),page:rect(pg),\",\"return {bar:rect(bar),title:rect(title),glyph:rect(title.querySelector('strong')),back:rect(back),frame:rect(frame),nav:rect(nav),page:rect(pg),\\n          top:rect(document.querySelector('.top')),workspace:rect(document.querySelector('.workspace')),paddingTop:parseFloat(s.paddingTop),paddingBottom:parseFloat(s.paddingBottom),dpr:devicePixelRatio,\",1],[\"budget=169 if width<=740 else 182\",\"budget=170 if width<=740 else 183\",1],[\"assert abs(bar[\\\"h\\\"]-45)<=.5\",\"assert abs(bar[\\\"h\\\"]-46)<=.5\",1],[\"        assert frame[\\\"y\\\"]>=bar[\\\"bottom\\\"]-.5 and frame[\\\"y\\\"]-bar[\\\"bottom\\\"]<=8,data\",\"        assert frame[\\\"y\\\"]>=bar[\\\"bottom\\\"]-.5 and frame[\\\"y\\\"]-bar[\\\"bottom\\\"]<=8,data\\n        # Measure the actual visible band between the global header and the video, not only the flex box.\\n        upper=bar[\\\"y\\\"]-data[\\\"top\\\"][\\\"bottom\\\"]\\n        lower=frame[\\\"y\\\"]-bar[\\\"bottom\\\"]\\n        center=(data[\\\"top\\\"][\\\"bottom\\\"]+frame[\\\"y\\\"])/2\\n        assert abs(data[\\\"workspace\\\"][\\\"y\\\"]-data[\\\"top\\\"][\\\"bottom\\\"])<=.5,data\\n        assert abs(upper-3)<=.5 and abs(lower-3)<=.5 and abs(upper-lower)<=.5,(upper,lower,data)\\n        assert data[\\\"paddingTop\\\"]==data[\\\"paddingBottom\\\"]==0,data\\n        assert abs(back[\\\"cy\\\"]-center)<=.5 and abs(title[\\\"cy\\\"]-center)<=.5,(center,data)\\n        assert abs(data[\\\"glyph\\\"][\\\"cy\\\"]-center-1)<=.6,(center,data)\\n        print('PASS Player surrounding centerline',width,height,'gaps',upper,lower,'DPR',data['dpr'],'Back delta',back['cy']-center,'optical title delta',data['glyph']['cy']-center,flush=True)\",1],[\"page=browser.new_page(viewport={\\\"width\\\":1440,\\\"height\\\":900},reduced_motion=motion)\",\"page=browser.new_page(viewport={\\\"width\\\":1440,\\\"height\\\":900},reduced_motion=motion,device_scale_factor=1+themes.index(theme)%2)\",1],[\"PASS 60 compact Player configurations, 12 fullscreen cycles and retained standard header geometry\",\"PASS 60 centered compact Player configurations, 12 fullscreen cycles and retained standard header geometry\",1]]"):
    assert source.count(old)==count,(old,source.count(old),count)
    source=source.replace(old,replacement)
exec(compile(source,str(original),"exec"),{"__name__":"__main__","__file__":str(original)})
